// Synthetic CharLS fixtures only; generated by Scripts/generate_precision_recovery_fixtures.py.
import Foundation
import Testing
@testable import DICOMCore

@Suite("Explicit JPEG-LS precision recovery")
struct JPEGLSPrecisionRecoveryTests {
    private let low = "/9j/9wALEAAIABABAREA//gADQH//wASAEMBFABA/9oACAEBAAAAAKK9pWAX/YAD/MAgCASK9o1//3cAT/eASAEAIAQAgBACAIAQAgCAIAgCAIBACAIAgCAIBAEAgCAIBAIBAIBAQBAEAgEAgIBAQBAEAgEAgIBAQBAIBAIBAQCAgEAgICAgICBAIBAQEBAgIEAgEBAQECAgQCAQEBAQICBAIBAQEBAgIEAgEBAQECAgQCAQEBAQICBAAP/Z"
    private let high = "/9j/9wALEAAIABABAREA//gADQH//wASAEMBFABA/9oACAEBAAAAAKAID/cAQAAAAAAAd/8QAAB/8wACAAoAv/MACA/+YAIP/rAAIAQAgBAEAQBAEAIAQCAQCAQCAQAgCAQCAgICAgCAICAgICAgIAgCAgICAgICAIAgQIECBAgCAQIECBAgQCAQIECBAgQCAQIECBAgQCAQIECBAgQCAQIEEEEEAgEEEEEEEAgEEEEEEEAgEEEEEEEA/9k="
    private let narrow = "/9j/9wALDAAIABABAREA/9oACAEBAAAAAJXAygAAAQQAAAAH2AAD+YAQBK7Rn/v8wEH9YAQIECBAgQQIEEEEEEIEEEEEIIQQQhCEIgghCEQiCCEIRCIIQhCIRCERERIQiIkSEIiJEhCIiRIQiIkSEIiJEhCIiRIA/9k="
    private func source(bits: Int = 12, signed: Bool = false, allocated: Int = 16,
                        pi: PhotometricInterpretation = .monochrome2) -> PixelDataDescriptor {
        PixelDataDescriptor(rows: 8, columns: 16, numberOfFrames: 3, bitsAllocated: allocated,
            bitsStored: bits, highBit: bits - 1, isSigned: signed, photometricInterpretation: pi)
    }
    private func codec(limit: Int = 64 << 20) -> JPEGLSCodec {
        JPEGLSCodec(decodingTransferSyntaxUID: TransferSyntax.jpegLSLossless.uid,
            decodingLimits: .init(maximumDecodedBytes: limit),
            precisionPolicy: .useCodestreamForUnsignedMonochrome)
    }
    private func bytes(_ value: String) throws -> Data { try #require(Data(base64Encoded: value)) }

    @Test func strictDefaultAndDataOnlyRemainStrict() throws {
        let data = try bytes(low)
        #expect(throws: DICOMError.self) { try JPEGLSCodec().decodePixelFrame(data, descriptor: source(), frameIndex: 2) }
        #expect(throws: DICOMError.self) { try codec().decodeFrame(data, descriptor: source(), frameIndex: 2) }
    }
    @Test func recoveryPreservesEveryBitAndReportsActualDescriptor() throws {
        for (encoded, values) in [(low, [0,44,255,1024,2047,2048,4094,4095]),
                                  (high, [0,1,4095,4096,32767,32768,65534,65535])] {
            let original = source()
            let decoder: any ImageCodec = codec()
            let result = try decoder.decodePixelFrame(bytes(encoded), descriptor: original, frameIndex: 2)
            let expected = Data(Array(repeating: values, count: 16).flatMap { $0 }.flatMap { [UInt8($0 & 255), UInt8($0 >> 8)] })
            #expect(result.data == expected)
            #expect(result.descriptor.bitsAllocated == 16 && result.descriptor.bitsStored == 16)
            #expect(result.descriptor.highBit == 15 && !result.descriptor.isSigned)
            #expect(result.descriptor.numberOfFrames == 3 && result.sourceFrameIndex == 2)
            #expect(result.diagnostics == [.sourcePrecisionMismatch(sourceBitsStored: 12, encodedPrecision: 16)])
            #expect(original.bitsStored == 12 && original.highBit == 11)
        }
    }
    @Test func inspectionAndDecodeShareInterpretationAndBounds() throws {
        for (encoded, bits) in [(low,12),(high,12),(low,16),(narrow,12)] {
            // A non-zero-index Data slice must behave like an ordinary frame.
            let padded = Data([0,0,0]) + (try bytes(encoded))
            let data = padded.dropFirst(3)
            let info = try codec().inspectFrame(data, descriptor: source(bits: bits), frameIndex: 2)
            let decoded = try codec().decodePixelFrame(data, descriptor: source(bits: bits), frameIndex: 2)
            #expect(info.descriptor == decoded.descriptor)
            #expect(info.sourceFrameIndex == decoded.sourceFrameIndex)
            #expect(info.diagnostics == decoded.diagnostics)
        }
        let data = try bytes(low)
        #expect(throws: DICOMError.self) { try JPEGLSCodec().inspectFrame(data, descriptor: source(), frameIndex: 0) }
        // Output needs 256 bytes; the decoder's 128 Int samples need 1024.
        for limit in [255, 256, 1023] {
            #expect(throws: DICOMError.self) { try codec(limit: limit).inspectFrame(data, descriptor: source(), frameIndex: 0) }
            #expect(throws: DICOMError.self) { try codec(limit: limit).decodePixelFrame(data, descriptor: source(), frameIndex: 0) }
        }
        #expect(try codec(limit: 1024).inspectFrame(data, descriptor: source(), frameIndex: 0).descriptor.bitsStored == 16)
        #expect(throws: DICOMError.self) { try codec().inspectFrame(data, descriptor: source(), frameIndex: 3) }
    }
    @Test func inspectionRejectsInvalidMaxvalAndOversizedSlices() throws {
        var invalid = try bytes(low)
        invalid[6] = 12 // SOF P=12 while LSE MAXVAL remains 65535.
        #expect(throws: DICOMError.self) { try codec().inspectFrame(invalid, descriptor: source(), frameIndex: 0) }
        #expect(throws: DICOMError.self) { try codec().decodePixelFrame(invalid, descriptor: source(), frameIndex: 0) }
        let data = (Data([0,0]) + (try bytes(low))).dropFirst(2)
        let bounded = JPEGLSCodec(decodingLimits: .init(maximumEncodedBytes: data.count - 1),
                                  precisionPolicy: .useCodestreamForUnsignedMonochrome)
        #expect(throws: DICOMError.self) { try bounded.inspectFrame(data, descriptor: source(), frameIndex: 0) }
        #expect(throws: DICOMError.self) { try bounded.decodePixelFrame(data, descriptor: source(), frameIndex: 0) }
    }
    @Test func matchingPrecisionHasNoRecoveryDiagnostic() throws {
        for (encoded, bits) in [(low,16),(narrow,12)] {
            let result = try codec().decodePixelFrame(bytes(encoded), descriptor: source(bits: bits), frameIndex: 0)
            #expect(result.descriptor.bitsStored == bits && result.diagnostics.isEmpty)
        }
    }
    @Test func rejectsUnqualifiedProfilesAndBounds() throws {
        let data = try bytes(low)
        for descriptor in [source(signed: true),source(bits: 8,allocated: 8),source(pi: .rgb)] {
            #expect(throws: DICOMError.self) { try codec().decodePixelFrame(data, descriptor: descriptor, frameIndex: 0) }
        }
        #expect(throws: DICOMError.self) { try codec().decodePixelFrame(bytes(narrow), descriptor: source(bits: 16), frameIndex: 0) }
        #expect(throws: DICOMError.self) { try codec(limit: 16).decodePixelFrame(data, descriptor: source(), frameIndex: 0) }
        #expect(throws: DICOMError.self) { try codec().decodePixelFrame(data, descriptor: source(), frameIndex: 3) }
        let wrongSyntax = JPEGLSCodec(decodingTransferSyntaxUID: TransferSyntax.jpegLSNearLossless.uid,
            precisionPolicy: .useCodestreamForUnsignedMonochrome)
        #expect(throws: DICOMError.self) { try wrongSyntax.decodePixelFrame(data, descriptor: source(), frameIndex: 0) }
    }
    @Test func refusesUnqualifiedScanTransformsAndMalformedEnvelope() throws {
        let data = try bytes(low)
        let start = try #require(data.range(of: Data([255,218]))).lowerBound
        let length = (Int(data[start+2]) << 8) | Int(data[start+3])
        for offset in [start + 6, start + 7, start + 2 + length - 1] {
            var bad = data; bad[offset] = 1 // mapping selector, NEAR, point transform
            #expect(throws: DICOMError.self) { try codec().decodePixelFrame(bad, descriptor: source(), frameIndex: 0) }
            #expect(throws: DICOMError.self) { try codec().inspectFrame(bad, descriptor: source(), frameIndex: 0) }
        }
        // APP8 mrfx transform1 is not a monochrome recovery profile.
        let transformed = Data(data.prefix(2)) + Data([255,232,0,7,109,114,102,120,1]) + data.dropFirst(2)
        #expect(throws: DICOMError.self) { try codec().decodePixelFrame(transformed, descriptor: source(), frameIndex: 0) }
        for bad in [Data(data.dropLast(2)), data + data, data + Data([1])] {
            #expect(throws: DICOMError.self) { try codec().decodePixelFrame(bad, descriptor: source(), frameIndex: 0) }
            #expect(throws: DICOMError.self) { try codec().inspectFrame(bad, descriptor: source(), frameIndex: 0) }
        }
    }
}
